def _hex4(text: str, i: int, n: int) -> int:
    if i + 4 > n:
        raise ValueError

    code = 0
    for k in range(i, i + 4):
        c = text[k]
        if '0' <= c <= '9':
            code = (code << 4) + (ord(c) - 48)
        elif 'a' <= c <= 'f':
            code = (code << 4) + (ord(c) - 97)
        elif 'A' <= c <= 'F':
            code = (code << 4) + (ord(c) - 87)
        else:
            raise ValueError

    return code


def _parse_string(text: str, i: int, n: int) -> tuple[str, int]:
    if i >= n or text[i] != '"':
        raise ValueError

    i += 1
    out: list[str] = []
    append = out.append
    chunk_start = i

    while i < n:
        c = text[i]

        if c == '"':
            if i > chunk_start:
                append(text[chunk_start:i])
            return ''.join(out), i + 1

        if c == '\\':
            if i > chunk_start:
                append(text[chunk_start:i])

            i += 1
            if i >= n:
                raise ValueError

            esc = text[i]
            if esc == '"':
                append('"')
                i += 1
            elif esc == '\\':
                append('\\')
                i += 1
            elif esc == '/':
                append('/')
                i += 1
            elif esc == 'b':
                append('\b')
                i += 1
            elif esc == 'f':
                append('\f')
                i += 1
            elif esc == 'n':
                append('\n')
                i += 1
            elif esc == 'r':
                append('\r')
                i += 1
            elif esc == 't':
                append('\t')
                i += 1
            elif esc == 'u':
                i += 1
                code = _hex4(text, i, n)
                i += 4

                if 0xD800 <= code <= 0xDBFF:
                    if i + 1 >= n or text[i] != '\\' or text[i + 1] != 'u':
                        raise ValueError

                    low_code = _hex4(text, i + 2, n)
                    if 0xDC00 <= low_code <= 0xDFFF:
                        code = 0x10000 + ((code - 0xD800) << 10) + (low_code - 0xDC00)
                        i += 6
                    else:
                        raise ValueError
                elif 0xDC00 <= code <= 0xDFFF:
                    raise ValueError

                append(chr(code))
            else:
                raise ValueError

            chunk_start = i
            continue

        if ord(c) < 0x20 or 0xD800 <= ord(c) <= 0xDFFF:
            raise ValueError

        i += 1

    raise ValueError


def _parse_number(text: str, i: int, n: int) -> tuple[object, int]:
    if i >= n:
        raise ValueError

    start = i

    if text[i] == '-':
        i += 1
        if i >= n:
            raise ValueError

    c = text[i]
    if c == '0':
        i += 1
        if i < n and '0' <= text[i] <= '9':
            raise ValueError
    elif '1' <= c <= '9':
        while i < n and '0' <= text[i] <= '9':
            i += 1
    else:
        raise ValueError

    is_float = False

    if i < n and text[i] == '.':
        is_float = True
        i += 1
        if i >= n or not ('0' <= text[i] <= '9'):
            raise ValueError
        while i < n and '0' <= text[i] <= '9':
            i += 1

    if i < n and text[i] in 'eE':
        is_float = True
        i += 1

        if i < n and text[i] in '+-':
            i += 1

        if i >= n or not ('0' <= text[i] <= '9'):
            raise ValueError

        while i < n and '0' <= text[i] <= '9':
            i += 1

    s = text[start:i]

    if is_float:
        try:
            return float(s), i
        except OverflowError:
            if s.startswith('-'):
                return float('-inf'), i
            return float('inf'), i

    return int(s), i


def _parse_scalar(text: str, i: int, n: int) -> tuple[object, int]:
    if i >= n:
        raise ValueError

    c = text[i]

    if c == '"':
        return _parse_string(text, i, n)

    if c == 't':
        if text.startswith('true', i):
            return True, i + 4
        raise ValueError

    if c == 'f':
        if text.startswith('false', i):
            return False, i + 5
        raise ValueError

    if c == 'n':
        if text.startswith('null', i):
            return None, i + 4
        raise ValueError

    if c == '-' or '0' <= c <= '9':
        return _parse_number(text, i, n)

    raise ValueError


def parse_json(text: str) -> object:
    n = len(text)
    ws = ' \t\n\r'

    i = 0
    while i < n and text[i] in ws:
        i += 1

    if i >= n:
        raise ValueError

    c = text[i]

    if c == '{':
        i += 1
        stack: list[list] = [[1, 0, {}, None]]
    elif c == '[':
        i += 1
        stack = [[0, 0, [], None]]
    else:
        value, i = _parse_scalar(text, i, n)
        while i < n and text[i] in ws:
            i += 1
        if i != n:
            raise ValueError
        return value

    def finish_value(frame: list, value: object) -> None:
        typ = frame[0]

        if typ == 0:
            frame[2].append(value)
            frame[1] = 1
        else:
            key = frame[3]
            obj = frame[2]
            if key in obj:
                raise ValueError
            obj[key] = value
            frame[3] = None
            frame[1] = 2

    while stack:
        while i < n and text[i] in ws:
            i += 1

        frame = stack[-1]
        typ = frame[0]
        state = frame[1]

        if typ == 0:
            if state == 0:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == ']':
                    i += 1
                    value = frame[2]
                    stack.pop()

                    if stack:
                        finish_value(stack[-1], value)
                    else:
                        while i < n and text[i] in ws:
                            i += 1
                        if i != n:
                            raise ValueError
                        return value
                elif c == '{':
                    stack.append([1, 0, {}, None])
                    i += 1
                elif c == '[':
                    stack.append([0, 0, [], None])
                    i += 1
                else:
                    value, i = _parse_scalar(text, i, n)
                    finish_value(frame, value)

                continue

            if state == 1:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == ']':
                    i += 1
                    value = frame[2]
                    stack.pop()

                    if stack:
                        finish_value(stack[-1], value)
                    else:
                        while i < n and text[i] in ws:
                            i += 1
                        if i != n:
                            raise ValueError
                        return value
                elif c == ',':
                    i += 1
                    frame[1] = 2
                else:
                    raise ValueError

                continue

            if state == 2:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == ']':
                    raise ValueError
                elif c == '{':
                    stack.append([1, 0, {}, None])
                    i += 1
                elif c == '[':
                    stack.append([0, 0, [], None])
                    i += 1
                else:
                    value, i = _parse_scalar(text, i, n)
                    finish_value(frame, value)

                continue

            raise ValueError

        if typ == 1:
            if state == 0:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == '}':
                    i += 1
                    value = frame[2]
                    stack.pop()

                    if stack:
                        finish_value(stack[-1], value)
                    else:
                        while i < n and text[i] in ws:
                            i += 1
                        if i != n:
                            raise ValueError
                        return value
                elif c == '"':
                    key, i = _parse_string(text, i, n)
                    frame[3] = key
                    frame[1] = 1
                else:
                    raise ValueError

                continue

            if state == 1:
                if i >= n or text[i] != ':':
                    raise ValueError
                i += 1
                frame[1] = 2
                continue

            if state == 2:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == '{':
                    stack.append([1, 0, {}, None])
                    i += 1
                elif c == '[':
                    stack.append([0, 0, [], None])
                    i += 1
                else:
                    value, i = _parse_scalar(text, i, n)
                    finish_value(frame, value)

                continue

            if state == 3:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == '}':
                    i += 1
                    value = frame[2]
                    stack.pop()

                    if stack:
                        finish_value(stack[-1], value)
                    else:
                        while i < n and text[i] in ws:
                            i += 1
                        if i != n:
                            raise ValueError
                        return value
                elif c == ',':
                    i += 1
                    frame[1] = 4
                else:
                    raise ValueError

                continue

            if state == 4:
                if i >= n:
                    raise ValueError

                c = text[i]
                if c == '}':
                    raise ValueError
                elif c == '"':
                    key, i = _parse_string(text, i, n)
                    frame[3] = key
                    frame[1] = 1
                else:
                    raise ValueError

                continue

            raise ValueError

    raise ValueError
